BenchmarkResult runCanonicalBenchmark() {
    const auto& positions =
        canonicalBenchPositions();

    std::uint64_t totalNodes = 0;
    std::uint64_t checksum =
        1469598103934665603ULL;

    const auto start =
        std::chrono::steady_clock::now();

    for (const BenchPosition& bench : positions) {
        const Position pos =
            fromFEN(bench.fen);

        SearchHistory history;
        history.push_back(
            pos.zobristKey
        );

        clearTranspositionTable();
        resetSearchStop();

        const SearchResult result =
            searchBestMove(
                pos,
                bench.depth,
                {},
                history
            );

        totalNodes += result.nodes;

        checksum =
            checksumMix(
                checksum,
                static_cast<std::uint64_t>(
                    result.score + 32000
                )
            );

        checksum =
            checksumMix(
                checksum,
                static_cast<std::uint64_t>(
                    result.bestMove.from + 1
                )
            );

        checksum =
            checksumMix(
                checksum,
                static_cast<std::uint64_t>(
                    result.bestMove.to + 1
                )
            );
    }

    const auto end =
        std::chrono::steady_clock::now();

    BenchmarkResult output{};

    output.totalNodes =
        totalNodes;

    output.seconds =
        std::chrono::duration<double>(
            end - start
        ).count();

    output.checksum =
        checksum;

    output.evaluator =
        (
            nnueEnabled() &&
            nnueLoaded()
        )
        ?
        "NNUE"
        :
        "Handcrafted";

    return output;
}

else if (
    command ==
    "benchmulti"
    ) {
    stopAndJoinUciSearch();

    int runs = 5;
    std::string arg;
    std::string extra;

    if (input >> arg) {
        std::size_t consumed = 0;

        try {
            runs =
                std::stoi(
                    arg,
                    &consumed
                );
        }
        catch (const std::exception&) {
            std::cout <<
                "Usage: benchmulti [positive run count]\n";
            continue;
        }

        if (
            consumed != arg.size()
            ||
            (input >> extra)
            ) {
            std::cout <<
                "Usage: benchmulti [positive run count]\n";
            continue;
        }
    }

    if (runs <= 0) {
        std::cout <<
            "Usage: benchmulti [positive run count]\n";
        continue;
    }

    if (runs > 100) {
        std::cout <<
            "benchmulti supports at most 100 runs.\n";
        continue;
    }

    std::vector<std::uint64_t> npsValues;
    std::vector<std::uint64_t> nodeValues;
    std::vector<std::uint64_t> checksumValues;
    std::vector<double> timeValues;

    chess::BenchmarkResult firstResult{};

    for (
        int i = 1;
        i <= runs;
        ++i
        ) {
        const chess::BenchmarkResult result =
            chess::runCanonicalBenchmark();

        const std::uint64_t nps =
            result.seconds > 0.0
            ?
            static_cast<std::uint64_t>(
                static_cast<double>(
                    result.totalNodes
                )
                /
                result.seconds
            )
            :
            0ULL;

        npsValues.push_back(nps);
        nodeValues.push_back(result.totalNodes);
        checksumValues.push_back(result.checksum);
        timeValues.push_back(result.seconds);

        std::cout <<
            "Run " <<
            i <<
            "/" <<
            runs <<
            ": " <<
            std::fixed <<
            std::setprecision(3) <<
            result.seconds <<
            " s, " <<
            nps <<
            " NPS\n";

        if (i == 1) {
            firstResult = result;
        }
    }

    std::vector<std::uint64_t> sortedNps =
        npsValues;

    std::sort(
        sortedNps.begin(),
        sortedNps.end()
    );

    const std::size_t middle =
        sortedNps.size() / 2;

    const std::uint64_t medianNps =
        sortedNps.size() % 2
        ?
        sortedNps[middle]
        :
        (
            sortedNps[middle - 1]
            +
            sortedNps[middle]
        )
        /
        2ULL;

    const bool consistent =
        std::all_of(
            nodeValues.begin(),
            nodeValues.end(),
            [&](std::uint64_t nodes) {
                return
                    nodes ==
                    firstResult.totalNodes;
            }
        )
        &&
        std::all_of(
            checksumValues.begin(),
            checksumValues.end(),
            [&](std::uint64_t checksum) {
                return
                    checksum ==
                    firstResult.checksum;
            }
        );

    const double totalTime =
        std::accumulate(
            timeValues.begin(),
            timeValues.end(),
            0.0
        );

    std::cout <<
        "\nKnightBot Multi-Run Benchmark\n" <<
        "Runs:                   " <<
        runs <<
        '\n' <<
        "Nodes per run:          " <<
        firstResult.totalNodes <<
        '\n' <<
        "Median NPS:             " <<
        medianNps <<
        '\n' <<
        "Minimum NPS:            " <<
        sortedNps.front() <<
        '\n' <<
        "Maximum NPS:            " <<
        sortedNps.back() <<
        '\n' <<
        "Checksum:               " <<
        firstResult.checksum <<
        '\n' <<
        "Regression consistency: " <<
        (
            consistent
            ?
            "PASSED"
            :
            "FAILED"
        ) <<
        '\n' <<
        "Evaluator:              " <<
        firstResult.evaluator <<
        '\n' <<
        std::fixed <<
        std::setprecision(3) <<
        "Total benchmark time:   " <<
        totalTime <<
        " s\n";
}
